(function(){
"use strict";
const PI=Math.PI,TAU=2*PI;

/* ── Materials ───────────────────────────────────── */
const M={
hero:{b:[195,140,70],l:[235,195,120],d:[110,75,35],s:[255,245,210],eB:[170,115,55],eL:[215,165,90],bgC:'#1e1e38',bgE:'#080818',glow:'rgba(200,160,80,'},
bronze:{b:[184,115,51],l:[215,150,80],d:[120,72,30],s:[255,225,150],eB:[155,95,40],eL:[195,130,60],bgC:'#1e1818',bgE:'#0a0808',glow:'rgba(184,115,51,'},
silver:{b:[192,192,210],l:[232,232,245],d:[125,125,145],s:[255,255,255],eB:[170,170,190],eL:[215,215,235],bgC:'#181828',bgE:'#08081a',glow:'rgba(200,200,220,'},
gold:{b:[255,215,0],l:[255,242,100],d:[185,155,0],s:[255,255,220],eB:[225,190,0],eL:[255,235,60],bgC:'#282018',bgE:'#1a1408',glow:'rgba(255,215,0,'},
black:{b:[32,28,40],l:[65,55,80],d:[16,12,20],s:[110,90,140],eB:[28,24,35],eL:[55,45,65],bgC:'#141420',bgE:'#06060e',glow:'rgba(80,60,120,'}
};

/* ── Helpers ─────────────────────────────────────── */
function rgb(c){return`rgb(${c[0]},${c[1]},${c[2]})`}
function rgba(c,a){return`rgba(${c[0]},${c[1]},${c[2]},${a})`}
function lerp(a,b,t){return[a[0]+(b[0]-a[0])*t,a[1]+(b[1]-a[1])*t,a[2]+(b[2]-a[2])*t]}
function darken(c,f){return[Math.max(0,Math.round(c[0]*f)),Math.max(0,Math.round(c[1]*f)),Math.max(0,Math.round(c[2]*f))]}
function lighten(c,f){return[Math.min(255,Math.round(c[0]+(255-c[0])*f)),Math.min(255,Math.round(c[1]+(255-c[1])*f)),Math.min(255,Math.round(c[2]+(255-c[2])*f))]}

/* ── Coin Renderer ───────────────────────────────── */
function renderCoin(canvas,time,mat){
const ctx=canvas.getContext('2d');
const w=canvas.width,h=canvas.height;
const cx=w/2,cy=h/2;
const R=Math.min(w,h)*0.33;
const T=R*0.09;

// Animation state
const theta=TAU*time;
const phi=PI*Math.sin(TAU*time);
const cosP=Math.cos(phi),sinP=Math.sin(phi);
const faceH=R*Math.abs(cosP);
const edgeH=T*Math.abs(sinP);

// ── 1. Background ──
const bgG=ctx.createRadialGradient(cx,cy,0,cx,cy,w*0.7);
bgG.addColorStop(0,mat.bgC);bgG.addColorStop(1,mat.bgE);
ctx.fillStyle=bgG;ctx.fillRect(0,0,w,h);

// ── 2. Ambient glow ──
const glowG=ctx.createRadialGradient(cx,cy,R*0.6,cx,cy,R*1.6);
glowG.addColorStop(0,mat.glow+'0.08)');
glowG.addColorStop(1,mat.glow+'0)');
ctx.fillStyle=glowG;ctx.fillRect(0,0,w,h);

// ── 3. Shadow ──
ctx.save();
ctx.translate(cx,cy+R*0.92+edgeH*0.4);
ctx.scale(1,0.22);
ctx.beginPath();ctx.arc(0,0,R*1.08,0,TAU);
ctx.fillStyle='rgba(0,0,0,0.3)';ctx.fill();
ctx.restore();

// ── 4. Edge band ──
if(edgeH>1.5){
drawEdgeBand(ctx,cx,cy,R,faceH,edgeH,theta,mat);
}

// ── 5. Visible face ──
if(faceH>3){
const isFront=cosP>0;
drawFace(ctx,cx,cy,R,faceH,theta,isFront,mat);
}

// ── 6. Specular highlight (moves with theta) ──
if(faceH>3){
const specOff=0.45;
const sx=cx+R*specOff*Math.cos(theta+0.3);
const sy=cy+faceH*specOff*0.6*Math.sin(theta+0.3);
const sR=R*0.35;
const spG=ctx.createRadialGradient(sx,sy,0,sx,sy,sR);
spG.addColorStop(0,rgba(mat.s,0.7));
spG.addColorStop(0.15,rgba(mat.s,0.35));
spG.addColorStop(0.45,rgba(mat.s,0.1));
spG.addColorStop(1,rgba(mat.s,0));
ctx.save();
ctx.beginPath();ctx.ellipse(cx,cy,R,faceH,0,0,TAU);ctx.clip();
ctx.fillStyle=spG;ctx.fillRect(cx-R,sy-sR,R*2,sR*2);
ctx.restore();
}

// ── 7. Rim light ──
if(edgeH>1){
const rimG=ctx.createRadialGradient(cx,cy,R*0.92,cx,cy,R+edgeH*0.5);
rimG.addColorStop(0,'rgba(0,0,0,0)');
rimG.addColorStop(0.5,rgba(darken(mat.l,0.5),0.15));
rimG.addColorStop(1,'rgba(0,0,0,0)');
ctx.fillStyle=rimG;
ctx.beginPath();ctx.ellipse(cx,cy,R+edgeH*0.5,faceH+edgeH*0.5,0,0,TAU);ctx.fill();
}
}

/* ── Edge band with reeds ────────────────────────── */
function drawEdgeBand(ctx,cx,cy,R,faceH,edgeH,theta,mat){
const silH=(faceH+edgeH)/2;
ctx.save();

// Fill silhouette
ctx.beginPath();ctx.ellipse(cx,cy,R,silH,0,0,TAU);
const eGrad=ctx.createLinearGradient(cx-R,cy-silH,cx+R,cy+silH);
eGrad.addColorStop(0,rgba(darken(mat.eB,0.6),1));
eGrad.addColorStop(0.3,rgba(mat.eL,1));
eGrad.addColorStop(0.5,rgba(mat.eB,1));
eGrad.addColorStop(0.7,rgba(lighten(mat.eB,0.3),1));
eGrad.addColorStop(1,rgba(darken(mat.eB,0.5),1));
ctx.fillStyle=eGrad;ctx.fill();

// Cut out face area
ctx.globalCompositeOperation='destination-out';
ctx.beginPath();ctx.ellipse(cx,cy,R,faceH/2,0,0,TAU);
ctx.fillStyle='rgba(0,0,0,1)';ctx.fill();
ctx.globalCompositeOperation='source-over';

// Draw individual reeds along the edge
const numReeds=40;
const reedStep=TAU/numReeds;
for(let i=0;i<numReeds;i++){
const a=i*reedStep;
const px=cx+R*Math.cos(a);
const py=cy+faceH*0.5*Math.sin(a);
const lightF=(Math.cos(a-theta*0.5-0.6)+1)/2;
const reedCol=lerp(darken(mat.eB,0.55),mat.eL,lightF*0.8+0.2);

ctx.save();
ctx.translate(px,py);
const rot=a+PI/2;
ctx.rotate(rot);
const rw=TAU*R/numReeds*0.55;
const rh=edgeH*0.6;
ctx.beginPath();
ctx.moveTo(-rw/2,-rh/2);
ctx.lineTo(-rw/4,-rh/2-edgeH*0.12);
ctx.lineTo(rw/4,-rh/2-edgeH*0.12);
ctx.lineTo(rw/2,-rh/2);
ctx.lineTo(rw/2,rh/2);
ctx.lineTo(rw/4,rh/2+edgeH*0.12);
ctx.lineTo(-rw/4,rh/2+edgeH*0.12);
ctx.lineTo(-rw/2,rh/2);
ctx.closePath();
ctx.fillStyle=rgb(Math.round(reedCol[0]),Math.round(reedCol[1]),Math.round(reedCol[2]));
ctx.fill();
ctx.restore();
}

// Edge specular
const esA=theta+0.8;
const esx=cx+R*Math.cos(esA);
const esy=cy+silH*Math.sin(esA);
const esG=ctx.createRadialGradient(esx,esy,0,esx,esy,edgeH*1.5);
esG.addColorStop(0,'rgba(255,255,255,0.35)');
esG.addColorStop(1,'rgba(255,255,255,0)');
ctx.fillStyle=esG;
ctx.fillRect(esx-edgeH*2,esy-edgeH*2,edgeH*4,edgeH*4);

ctx.restore();
}

/* ── Face rendering ──────────────────────────────── */
function drawFace(ctx,cx,cy,R,faceH,theta,isFront,mat){
ctx.save();
ctx.beginPath();ctx.ellipse(cx,cy,R,faceH,0,0,TAU);ctx.clip();

// Base metallic gradient (subtle curvature)
const bG=ctx.createRadialGradient(cx-R*0.3,cy-faceH*0.3,0,cx,cy,R*1.1);
bG.addColorStop(0,rgb(mat.l));
bG.addColorStop(0.45,rgb(mat.b));
bG.addColorStop(0.85,rgb(mat.d));
bG.addColorStop(1,rgb(darken(mat.d,0.7)));
ctx.fillStyle=bG;
ctx.fillRect(cx-R*1.2,cy-faceH*1.2,R*2.4,faceH*2.4);

// Directional light overlay (top-left)
const dG=ctx.createLinearGradient(cx-R,cy-faceH,cx+R,cy+faceH);
dG.addColorStop(0,rgba(lighten(mat.l,0.3),0.25));
dG.addColorStop(0.4,rgba(mat.b,0));
dG.addColorStop(1,rgba(darken(mat.d,0.5),0.2));
ctx.fillStyle=dG;
ctx.fillRect(cx-R*1.2,cy-faceH*1.2,R*2.4,faceH*2.4);

// Scale factor for drawing face content
const sc=Math.min(1,faceH/R);

ctx.save();
ctx.translate(cx,cy);
ctx.scale(1,sc);
ctx.rotate(theta);

if(isFront) drawFrontContent(ctx,R,mat);
else drawBackContent(ctx,R,mat);

ctx.restore();

// Rim shadow (inner edge darkening)
const rG=ctx.createRadialGradient(cx,cy,R*0.78,cx,cy,R);
rG.addColorStop(0,'rgba(0,0,0,0)');
rG.addColorStop(0.6,'rgba(0,0,0,0.15)');
rG.addColorStop(1,'rgba(0,0,0,0.45)');
ctx.fillStyle=rG;
ctx.fillRect(cx-R*1.2,cy-faceH*1.2,R*2.4,faceH*2.4);

// Subtle highlight ring at the rim
ctx.beginPath();ctx.ellipse(cx,cy,R*0.96,faceH*0.96,0,0,TAU);
ctx.strokeStyle=rgba(lighten(mat.l,0.4),0.2);
ctx.lineWidth=2;ctx.stroke();

ctx.restore();
}

/* ── Front face content ──────────────────────────── */
function drawFrontContent(ctx,R,mat){
// Outer decorative ring
drawRing(ctx,R*0.93,R*0.89,mat);
// Inner decorative ring
drawRing(ctx,R*0.84,R*0.815,mat);
// Dotted border
for(let i=0;i<32;i++){
const a=(i/32)*TAU;
const dx=R*0.875*Math.cos(a);
const dy=R*0.875*Math.sin(a);
ctx.beginPath();ctx.arc(dx,dy,1.8,0,TAU);
ctx.fillStyle=rgba(darken(mat.b,0.5),0.7);ctx.fill();
}
// Second dotted border
for(let i=0;i<32;i++){
const a=(i/32)*TAU+TAU/64;
const dx=R*0.915*Math.cos(a);
const dy=R*0.915*Math.sin(a);
ctx.beginPath();ctx.arc(dx,dy,1.2,0,TAU);
ctx.fillStyle=rgba(lighten(mat.b,0.3),0.5);ctx.fill();
}

// Shield emblem
drawShield(ctx,0,0,R*0.42,mat);

// "WT" initials with emboss
ctx.save();
ctx.textAlign='center';ctx.textBaseline='middle';
ctx.font=`bold ${R*0.24}px Georgia,serif`;
ctx.fillStyle=rgba(darken(mat.b,0.45),0.9);
ctx.fillText('WT',0,R*0.04);
// Highlight offset
ctx.font=`bold ${R*0.24}px Georgia,serif`;
ctx.fillStyle=rgba(lighten(mat.b,0.5),0.6);
ctx.fillText('WT',-1.2,R*0.04-1.2);
ctx.restore();

// Arc text top: "WASTED TOKEN MINT"
drawArcText(ctx,R*0.74,'WASTED TOKEN MINT',-PI,0,mat,R);
// Arc text bottom: "MMXXIV • XXI • XXIV"
drawArcText(ctx,R*0.74,'MMXXIV  •  XXI  •  XXIV',0,PI,mat,R);

// Corner stars
[[-1,-1],[1,-1],[-1,1],[1,1]].forEach(([sx,sy])=>{
drawStar(ctx,sx*R*0.58,sy*R*0.42,R*0.045,mat);
});
}

/* ── Back face content ───────────────────────────── */
function drawBackContent(ctx,R,mat){
drawRing(ctx,R*0.93,R*0.89,mat);
drawRing(ctx,R*0.84,R*0.815,mat);
for(let i=0;i<32;i++){
const a=(i/32)*TAU;
const dx=R*0.875*Math.cos(a);
const dy=R*0.875*Math.sin(a);
ctx.beginPath();ctx.arc(dx,dy,1.8,0,TAU);
ctx.fillStyle=rgba(darken(mat.b,0.5),0.7);ctx.fill();
}

// "10,000" large
ctx.save();ctx.textAlign='center';ctx.textBaseline='middle';
ctx.font=`bold ${R*0.17}px Georgia,serif`;
ctx.fillStyle=rgba(darken(mat.b,0.5),0.9);
ctx.fillText('10,000',0,-R*0.12);
ctx.fillStyle=rgba(lighten(mat.b,0.5),0.5);
ctx.fillText('10,000',-1.2,-R*0.12-1.2);

