<script>
(function(){
"use strict";

/* ====== UTILITIES ====== */
function lerp(a,b,t){return a+(b-a)*t;}
function clamp(v,lo,hi){return v<lo?lo:v>hi?hi:v;}
function mix(c1,c2,t){return[lerp(c1[0],c2[0],t),lerp(c1[1],c2[1],t),lerp(c1[2],c2[2],t)];}
function rgb(c){return`rgb(${c[0]|0},${c[1]|0},${c[2]|0})`;}
function rgba(c,a){return`rgba(${c[0]|0},${c[1]|0},${c[2]|0},${a})`;}
function dist3(a,b){let dx=a[0]-b[0],dy=a[1]-b[1],dz=a[2]-b[2];return Math.sqrt(dx*dx+dy*dy+dz*dz);}
function normalize3(v){let l=Math.sqrt(v[0]*v[0]+v[1]*v[1]+v[2]*v[2]);return l>0?[v[0]/l,v[1]/l,v[2]/l]:[0,0,0];}
function cross3(a,b){return[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]];}
function dot3(a,b){return a[0]*b[0]+a[1]*b[1]+a[2]*b[2];}
function rotateY(v,a){let c=Math.cos(a),s=Math.sin(a);return[v[0]*c+v[2]*s,v[1],-v[0]*s+v[2]*c];}
function rotateX(v,a){let c=Math.cos(a),s=Math.sin(a);return[v[0],v[1]*c-v[2]*s,v[1]*s+v[2]*c];}

/* ====== METAL PALETTES ====== */
const METALS = {
  bronze: {
    base:[180,120,60], bright:[210,160,90], dark:[100,65,30],
    edge:[150,100,50], spec:[255,220,140]
  },
  silver: {
    base:[170,175,185], bright:[210,215,225], dark:[100,105,115],
    edge:[140,145,155], spec:[255,255,255]
  },
  gold: {
    base:[200,170,60], bright:[240,210,100], dark:[130,100,30],
    edge:[170,140,50], spec:[255,240,170]
  },
  black: {
    base:[35,35,45], bright:[60,60,75], dark:[15,15,22],
    edge:[30,30,40], spec:[100,100,140]
  }
};

/* ====== COIN RENDERER ====== */
class CoinRenderer {
  constructor(canvas, opts={}){
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.size = opts.size || 500;
    this.coinRadius = opts.coinRadius || 0.35;
    this.coinThickness = opts.coinThickness || 0.06;
    this.metal = opts.metal || 'bronze';
    this.frontFn = opts.frontFn || null;
    this.backFn = opts.backFn || null;
    this.numReeds = opts.numReeds || 48;
    this.paused = false;
    this.time = 0;
    this.bgColor = opts.bgColor || [10,10,15];
    this.glowColor = opts.glowColor || [200,170,80];
    this.showGlow = opts.showGlow !== false;
    this.staticT = null; // for setTime
    this.setSize(this.size, this.size);
  }

  setSize(w,h){
    this.canvas.width = w * devicePixelRatio;
    this.canvas.height = h * devicePixelRatio;
    this.canvas.style.width = w+'px';
    this.canvas.style.height = h+'px';
    this.ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);
    this.w = w; this.h = h;
    this.cx = w/2; this.cy = h/2;
    this.screenRadius = Math.min(w,h) * 0.42;
  }

  render(t){
    t = clamp(t,0,1);
    const ctx = this.ctx;
    const W = this.w, H = this.h;

    // Clear
    ctx.clearRect(0,0,W,H);

    // Background
    const bgGrad = ctx.createRadialGradient(W/2,H*0.45,0,W/2,H/2,W*0.7);
    bgGrad.addColorStop(0, rgba(this.bgColor, 1));
    bgGrad.addColorStop(1, 'rgba(5,5,8,1)');
    ctx.fillStyle = bgGrad;
    ctx.fillRect(0,0,W,H);

    // Ambient glow behind coin
    if(this.showGlow){
      const glowR = this.screenRadius * 1.8;
      const glow = ctx.createRadialGradient(W/2,H/2,this.screenRadius*0.5,W/2,H/2,glowR);
      glow.addColorStop(0, rgba(this.glowColor, 0.06));
      glow.addColorStop(1, 'rgba(0,0,0,0)');
      ctx.fillStyle = glow;
      ctx.beginPath();
      ctx.arc(W/2,H/2,glowR,0,Math.PI*2);
      ctx.fill();
    }

    // Animation angles
    const angleY = t * Math.PI * 2;           // full vertical spin
    const angleX = Math.sin(t * Math.PI * 2) * 0.45; // gentle flip

    this._drawCoin3D(ctx, angleY, angleX);
  }

  _drawCoin3D(ctx, angleY, angleX){
    const W=this.w, H=this.h, cx=W/2, cy=H/2;
    const R = this.coinRadius;
    const T = this.coinThickness;
    const metal = METALS[this.metal];

    // Camera setup
    const camDist = 4;
    const perspective = 6;

    // Coin center in world space (slightly offset for visual balance)
    const coinCenter = [0, 0, 0];

    // Compute transform matrix for the coin
    function worldToScreen(wp){
      let p = [wp[0], wp[1], wp[2]];
      p = rotateY(p, angleY);
      p = rotateX(p, angleX);
      // Camera at (0, 0, -camDist)
      let camZ = p[2] - camDist;
      if(camZ > 0) return null; // behind camera
      let scale = perspective / (perspective - p[2]);
      return [
        cx + p[0] * scale * this.screenRadius / R,
        cy - p[1] * scale * this.screenRadius / R
      ];
    }
    const worldToScreenB = worldToScreen.bind(this);

    // Determine which face is visible
    // Front face normal (in coin local space): (0,0,1)  Back: (0,0,-1)
    let frontNormal = [0,0,1];
    frontNormal = rotateY(frontNormal, angleY);
    frontNormal = rotateX(frontNormal, angleX);
    let backNormal = [0,0,-1];
    backNormal = rotateY(backNormal, angleY);
    backNormal = rotateX(backNormal, angleX);

    // Light direction (world space)
    const lightDir = normalize3([0.4, 0.6, -0.8]);
    const lightDirRotated = [lightDir[0], lightDir[1], lightDir[2]];

    // Front face dot with light (how much of front we see)
    const frontDot = dot3(normalize3([0,0,1]), normalize3([-frontNormal[0],-frontNormal[1],-frontNormal[2]]));
    const frontVisible = frontDot > 0.05;
    const backVisible = dot3(normalize3([0,0,1]), normalize3([-backNormal[0],-backNormal[1],-backNormal[2]])) > 0.05;

    // Draw shadow
    ctx.save();
    ctx.beginPath();
    const shadowY = cy + this.screenRadius * 0.85;
    ctx.ellipse(cx, shadowY, this.screenRadius * 0.7, this.screenRadius * 0.12, 0, 0, Math.PI*2);
    const shGrad = ctx.createRadialGradient(cx,shadowY,0,cx,shadowY,this.screenRadius*0.7);
    shGrad.addColorStop(0,'rgba(0,0,0,0.35)');
    shGrad.addColorStop(1,'rgba(0,0,0,0)');
    ctx.fillStyle = shGrad;
    ctx.fill();
    ctx.restore();

    // Draw coin body
    // We'll draw the coin as: back face (if visible) -> edge -> front face (if visible)
    // Compute projected points for the coin rim
    const rimPoints = [];
    const N = 120;
    for(let i=0;i<=N;i++){
      const a = (i/N)*Math.PI*2;
      // Rim point on front face edge
      const fp = [Math.cos(a)*R, Math.sin(a)*R, T*0.5];
      const bp = [Math.cos(a)*R, Math.sin(a)*R, -T*0.5];
      const fs = worldToScreenB(fp);
      const bs = worldToScreenB(bp);
      rimPoints.push({front:fs, back:bs, angle:a, fp, bp});
    }

    // Determine which rim points are visible (z-test against camera)
    const frontZ = rotateY(rotateX([0,0,T*0.5], angleY), angleX)[2];
    const backZ = rotateY(rotateX([0,0,-T*0.5], angleY), angleX)[2];

    // Draw edge first (behind faces)
    this._drawEdge(ctx, rimPoints, frontZ, backZ, metal, lightDirRotated);

    // Draw visible face
    const facingFront = frontZ < backZ; // front face closer to camera
    if(facingFront){
      this._drawFace(ctx, rimPoints, 'front', metal, lightDirRotated, frontNormal, angleY, angleX);
    } else {
      this._drawFace(ctx, rimPoints, 'back', metal, lightDirRotated, backNormal, angleY, angleX);
    }

    // Specular highlight that rakes across
    this._drawSpecular(ctx, rimPoints, metal, facingFront, angleY, angleX);
  }

  _drawEdge(ctx, rimPoints, frontZ, backZ, metal){
    const R = this.coinRadius;
    const T = this.coinThickness;

    // Determine visible portion of edge based on view angle
    const frontEdgeZ = frontZ;
    const backEdgeZ = backZ;

    // Draw the edge as a band between front and back rims
    // Only draw the half that faces the camera
    ctx.save();

    // Collect visible edge segments
    const visibleSegments = [];
    for(let i=0;i<rimPoints.length-1;i++){
      const rp = rimPoints[i];
      const rp2 = rimPoints[i+1];
      if(!rp.front || !rp2.front || !rp.back || !rp2.back) continue;

      // Average Z of these points
      const avgZ = (rp.fp[2]+rp.bp[2]+rp2.fp[2]+rp2.bp[2])/4;
      const rotFP = rotateY(rotateX(rp.fp, angleY), angleX);
      const rotBP = rotateY(rotateX(rp.bp, angleY), angleX);
      const avgZRot = (rotFP[2]+rotBP[2])/2;

      // Only draw if between front and back (visible from side)
      if(avgZRot < -0.5 && avgZRot > -1.5){
        visibleSegments.push({rp, rp2, avgZ:avgZRot});
      }
    }

    // Draw edge as filled band
    if(visibleSegments.length > 2){
      ctx.beginPath();
      ctx.moveTo(visibleSegments[0].rp.front[0], visibleSegments[0].rp.front[1]);
      for(let i=1;i<visibleSegments.length;i++){
        ctx.lineTo(visibleSegments[i].rp.front[0], visibleSegments[i].rp.front[1]);
      }
      for(let i=visibleSegments.length-1;i>=0;i--){
        ctx.lineTo(visibleSegments[i].rp.back[0], visibleSegments[i].rp.back[1]);
      }
      ctx.closePath();

      // Edge gradient (reeded effect)
      const grad = ctx.createLinearGradient(0,0,0,this.h);
      const midColor = mix(metal.edge, metal.bright, 0.3);
      grad.addColorStop(0, rgb(metal.dark));
      grad.addColorStop(0.3, rgb(midColor));
      grad.addColorStop(0.5, rgb(metal.bright));
      grad.addColorStop(0.7, rgb(midColor));
      grad.addColorStop(1, rgb(metal.dark));
      ctx.fillStyle = grad;
      ctx.fill();
    }

    // Draw reed lines on visible edge
    const numReedLines = this.numReeds;
    for(let i=0;i<visibleSegments.length;i++){
      const seg = visibleSegments[i];
      const rx = (seg.rp.front[0]+seg.rp.back[0])/2;
      const ry = (seg.rp.front[1]+seg.rp.back[1])/2;
      const len = Math.sqrt(
        Math.pow(seg.rp.front[0]-seg.rp.back[0],2)+
        Math.pow(seg.rp.front[1]-seg.rp.back[1],2)
      );
      if(len < 1) continue;

      const angle = Math.atan2(seg.rp.back[1]-seg.rp.front[1], seg.rp.back[0]-seg.rp.front[0]);

      // Alternate light/dark reeds
      const brightness = (i % 2 === 0) ? 0.7 : 0.3;
      const reedColor = mix(metal.edge, metal.bright, brightness * 0.4);

      ctx.strokeStyle = rgba(reedColor, 0.6);
      ctx.lineWidth = Math.max(0.5, len * 0.15);
      ctx.beginPath();
      ctx.moveTo(seg.rp.front[0], seg.rp.front[1]);
      ctx.lineTo(seg.rp.back[0], seg.rp.back[1]);
      ctx.stroke();
    }

    ctx.restore();
  }

  _drawFace(ctx, rimPoints, side, metal, lightDir, faceNormal, angleY, angleX){
    const R = this.coinRadius;
    const T = this.coinThickness;
    const N = rimPoints.length;

    ctx.save();

    // Build face polygon
    const faceZ = side === 'front' ? T*0.5 : -T*0.5;
    const facePoints = [];

    for(let i=0;i<N;i++){
      const rp = rimPoints[i];
      const p = side === 'front' ? rp.front : rp.back;
      if(p) facePoints.push(p);
    }

    if(facePoints.length < 3) { ctx.restore(); return; }

    // Draw face shape
    ctx.beginPath();
    ctx.moveTo(facePoints[0][0], facePoints[0][1]);
    for(let i=1;i<facePoints.length;i++){
      ctx.lineTo(facePoints[i][0], facePoints[i][1]);
    }
    ctx.closePath();
    ctx.clip();

    // Face base gradient (metallic)
    const cx = this.w/2, cy = this.h/2;
    const grad = ctx.createRadialGradient(
      cx - this.screenRadius*0.2, cy - this.screenRadius*0.2, 0,
      cx, cy, this.screenRadius * 1.2
    );
    grad.addColorStop(0, rgb(metal.bright));
    grad.addColorStop(0.4, rgb(metal.base));
    grad.addColorStop(0.8, rgb(metal.dark));
    grad.addColorStop(1, rgb(mix(metal.dark, [0,0,0], 0.3)));
    ctx.fillStyle = grad;
    ctx.fill();

    // Inner ring
    ctx.beginPath();
    ctx.arc(cx, cy, this.screenRadius * 0.92, 0, Math.PI*2);
    ctx.strokeStyle = rgba(metal.bright, 0.3);
    ctx.lineWidth = 1.5;
    ctx.stroke();

    // Draw face content
    if(side === 'front' && this.frontFn){
      this.frontFn(ctx, cx, cy, this.screenRadius, metal);
    } else if(side === 'back' && this.backFn){
      this.backFn(ctx, cx, cy, this.screenRadius, metal);
    }

    // Rim highlight
    ctx.beginPath();
    ctx.arc(cx, cy, this.screenRadius * 0.95, 0, Math.PI*2);
    ctx.strokeStyle = rgba(metal.bright, 0.25);
    ctx.lineWidth = 2;
    ctx.stroke();

    ctx.restore();
  }

  _drawSpecular(ctx, rimPoints, metal, facingFront, angleY, angleX){
    // Specular highlight that moves as coin rotates
    const N = rimPoints.length;
    const cx = this.w/2, cy = this.h/2;
    const R = this.screenRadius;

    // Specular position moves based on rotation
    const specAngle = angleY * 0.5 + Math.PI * 0.25;
    const specOffset = 0.3;
    const sx = cx + Math.cos(specAngle) * R * specOffset;
    const sy = cy + Math.sin(specAngle * 0.7) * R * specOffset * 0.5;

    const specGrad = ctx.createRadialGradient(sx, sy, 0, sx, sy, R * 0.6);
    specGrad.addColorStop(0, rgba(metal.spec, 0.35));
    specGrad.addColorStop(0.3, rgba(metal.spec, 0.12));
    specGrad.addColorStop(1, 'rgba(0,0,0,0)');

    // Clip to coin shape
    ctx.save();
    ctx.beginPath();
    const faceSide = facingFront ? 'front' : 'back';
    for(let i=0;i<N;i++){
      const rp = rimPoints[i];
      const p = faceSide === 'front' ? rp.front : rp.back;
      if(p) {
        if(i===0) ctx.moveTo(p[0],p[1]);
        else ctx.lineTo(p[0],p[1]);
      }
    }
    ctx.closePath();
    ctx.clip();
    ctx.fillStyle = specGrad;
    ctx.fillRect(0,0,this.w,this.h);
    ctx.restore();

    // Secondary specular (rim edge highlight)
    const rimSpecX = cx + Math.cos(angleY + Math.PI*0.5) * R * 0.8;
    const rimSpecY = cy - R * 0.3;
    const rimGrad = ctx.createRadialGradient(rimSpecX, rimSpecY, 0, rimSpecX, rimSpecY, R*0.4);
    rimGrad.addColorStop(0, rgba(metal.spec, 0.15));
    rimGrad.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.save();
    ctx.beginPath();
    for(let i=0;i<N;i++){
      const rp = rimPoints[i];
      const p = faceSide === 'front' ? rp.front : rp.back;
      if(p) {
        if(i===0) ctx.moveTo(p[0],p[1]);
        else ctx.lineTo(p[0],p[1]);
      }
    }
    ctx.closePath();
    ctx.clip();
    ctx.fillStyle = rimGrad;
    ctx.fillRect(0,0,this.w,this.h);
    ctx.restore();
  }
}

/* ====== FACE DRAWING FUNCTIONS ====== */
function drawFrontFace(ctx, cx, cy, R, metal){
  // WastedToken Mint emblem
  ctx.save();

  // Outer text circle
  ctx.font = `bold ${R*0.12}px 'Segoe UI', system-ui, sans-serif`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = rgba(mix(metal.dark, [0,0,0], 0.3), 0.7);

  const textR = R * 0.82;
  const segments = 40;
  const frontText = 'WASTED TOKEN MINT • WASTED TOKEN MINT • ';
  for(let i=0;i<segments;i++){
    const a = (i/segments)*Math.PI*2 - Math.PI/2;
    const charIdx = Math.floor((i/segments) * frontText.length) % frontText.length;
    const char = frontText[charIdx];
    if(char === ' ') continue;
    const x = cx + Math.cos(a) * textR;
    const y = cy + Math.sin(a) * textR;
    const cos = Math.cos(a - Math.PI/2);
    const sin = Math.sin(a - Math.PI/2);
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(a - Math.PI/2);
    ctx.fillText(char, 0, 0);
    ctx.restore();
  }

  // Inner decorative ring
  ctx.beginPath();
  ctx.arc(cx, cy, R*0.7, 0, Math.PI*2);
  ctx.strokeStyle = rgba(metal.bright, 0.3);
  ctx.lineWidth = 1;
  ctx.stroke();

  // Star/Emblem in center - draw a detailed 8-pointed star
  const starR = R * 0.35;
  const starInnerR = R * 0.18;
  const points = 8;

  ctx.beginPath();
  for(let i=0;i<points*2;i++){
    const a = (i/(points*2))*Math.PI*2 - Math.PI/2;
    const r = i%2===0 ? starR : starInnerR;
    const x = cx + Math.cos(a)*r;
    const y = cy + Math.sin(a)*r;
    if(i===0) ctx.moveTo(x,y);
    else ctx.lineTo(x,y);
  }
  ctx.closePath();

  const starGrad = ctx.createRadialGradient(cx, cy, 0, cx, cy, starR);
  starGrad.addColorStop(0, rgba(metal.bright, 0.8));
  starGrad.addColorStop(0.5, rgba(metal.base, 0.6));
  starGrad.addColorStop(1, rgba(metal.dark, 0.4));
  ctx.fillStyle = starGrad;
  ctx.fill();
  ctx.strokeStyle = rgba(metal.bright, 0.5);
  ctx.lineWidth = 1.5;
  ctx.stroke();

  // "WT" in center of star
  ctx.font = `bold ${R*0.2}px 'Segoe UI', system-ui, sans-serif`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = rgba(mix(metal.dark, [0,0,0], 0.4), 0.9);
  ctx.fillText('WT', cx, cy);

  // Small decorative dots around inner ring
  for(let i=0;i<16;i++){
    const a = (i/16)*Math.PI*2;
    const dx = cx + Math.cos(a)*R*0.55;
    const dy = cy + Math.sin(a)*R*0.55;
    ctx.beginPath();
    ctx.arc(dx, dy, R*0.015, 0, Math.PI*2);
    ctx.fillStyle = rgba(metal.bright, 0.4);
    ctx.fill();
  }

  ctx.restore();
}

function drawBackFace(ctx, cx, cy, R, metal){
  ctx.save();

  // Back face text: "10,000 TOKENS"
  ctx.font = `bold ${R*0.22}px 'Segoe UI', system-ui, sans-serif`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = rgba(mix(metal.dark, [0,0,0], 0.3), 0.8);
  ctx.fillText('10,000', cx, cy - R*0.12);

  ctx.font = `bold ${R*0.11}px 'Segoe UI', system-ui, sans-serif`;
  ctx.fillStyle = rgba(mix(metal.dark, [0,0,0], 0.25), 0.7);
  ctx.fillText('TOKENS', cx, cy + R*0.12);

  // Decorative lines
  ctx.strokeStyle = rgba(metal.bright, 0.2);
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(cx - R*0.4, cy - R*0.01);
  ctx.lineTo(cx + R*0.4, cy - R*0.01);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(cx - R*0.4, cy + R*0.25);
  ctx.lineTo(cx + R*0.4, cy + R*0.25);
  ctx.stroke();

  // Year at bottom
  ctx.font = `${R*0.08}px 'Segoe UI', system-ui, sans-serif`;
  ctx.fillStyle = rgba(metal.dark, 0.5);
  ctx.fillText('MMXXV', cx, cy + R*0.35);

  // Corner decorations
  const cornerR = R * 0.6;
  for(let i=0;i<4;i++){
    const a = (i/4)*Math.PI*2 + Math.PI/4;
    const dx = cx + Math.cos(a)*cornerR;
    const dy = cy + Math.sin(a)*cornerR;
    ctx.beginPath();
    ctx.arc(dx, dy, R*0.03, 0, Math.PI*2);
    ctx.fillStyle = rgba(metal.bright, 0.2);
    ctx.fill();
  }

  ctx.restore();
}

/* ====== EDITION COIN RENDERERS ====== */
function drawEditionFace(ctx, cx, cy, R, metal, edition){
  ctx.save();
  const metalData = METALS[edition] || METALS.bronze;

  // Base fill
  const grad = ctx.createRadialGradient(cx-R*0.2, cy-R*0.2, 0, cx, cy, R);
  grad.addColorStop(0, rgb(metalData.bright));
  grad.addColorStop(0.5, rgb(metalData.base));
  grad.addColorStop(1, rgb(metalData.dark));
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.arc(cx, cy, R, 0, Math.PI*2);
  ctx.fill();

  // Rim
  ctx.beginPath();
  ctx.arc(cx, cy, R*0.93, 0, Math.PI*2);
  ctx.strokeStyle = rgba(metalData.bright, 0.3);
  ctx.lineWidth = 1;
  ctx.stroke();

  // Edition-specific emblem
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';

  if(edition === 'bronze'){
    // Shield
    ctx.font = `bold ${R*0.5}px 'Segoe UI', system-ui, sans-serif`;
    ctx.fillStyle = rgba(mix(metalData.dark,[0,0,0],0.3), 0.7);
    ctx.fillText('⛊', cx, cy);
    ctx.font = `bold ${R*0.12}px 'Segoe UI', system-ui, sans-serif`;
    ctx.fillText('VANGUARD', cx, cy+R*0.4);
  } else if(edition === 'silver'){
    ctx.font = `bold ${R*0.5}px 'Segoe UI', system-ui, sans-serif`;
    ctx.fillStyle = rgba(mix(metalData.dark,[0,0,0],0.3), 0.7);
    ctx.fillText('☆', cx, cy);
    ctx.font = `bold ${R*0.12}px 'Segoe UI', system-ui, sans-serif`;
    ctx.fillText('SENTINEL', cx, cy+R*0.4);
  } else if(edition === 'gold'){
    ctx.font = `bold ${R*0.5}px 'Segoe UI', system-ui, sans-serif`;
    ctx.fillStyle = rgba(mix(metalData.dark,[0,0,0],0.3), 0.7);
    ctx.fillText('♛', cx, cy);
    ctx.font = `bold ${R*0.12}px 'Segoe UI', system-ui, sans-serif`;
    ctx.fillText('SOVEREIGN', cx, cy+R*0.4);
  } else {
    // Obsidian - dark with subtle glow
    ctx.beginPath();
    ctx.arc(cx, cy, R*0.4, 0, Math.PI*2);
    ctx.fillStyle = 'rgba(60,60,80,0.5)';
    ctx.fill();
    ctx.font = `bold ${R*0.35}px 'Segoe UI', system-ui, sans-serif`;
    ctx.fillStyle = 'rgba(120,140,200,0.6)';
    ctx.fillText('◆', cx, cy);
    ctx.font = `bold ${R*0.12}px 'Segoe UI', system-ui, sans-serif`;
    ctx.fillStyle = 'rgba(100,110,150,0.5)';
    ctx.fillText('PHANTOM', cx, cy+R*0.4);
  }

  ctx.restore();
}

